import { Link } from "react-router-dom";
import { useAuth } from "../../context/AuthContext.jsx";

// Fully self-contained dashboard: both premium gift images are included
// as WebP data URLs so no separate image files or asset imports are needed.
const dashboardHeroArt = "data:image/webp;base64,";
const dashboardStudioArt = "data:image/webp;base64,";

const DISPLAY_FONT = "'Cormorant Garamond', 'Playfair Display', Georgia, serif";

const DASHBOARD_STYLES = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Manrope:wght@400;500;600;700;800&display=swap');
.hdf-page{--gold:#b7892c;--bright:#eac65a;--ink:#191713;--ease:cubic-bezier(.16,1,.3,1);position:relative;display:block;width:100%;max-width:100%;min-width:0;margin:0;background:#faf8f3;color:var(--ink);font-family:'Manrope',Arial,sans-serif;-webkit-font-smoothing:antialiased;overflow-x:clip;container-type:inline-size;container-name:hdf-dashboard}
.hdf-page *,.hdf-page *::before,.hdf-page *::after{box-sizing:border-box}
.hdf-page a{color:inherit;text-decoration:none;-webkit-tap-highlight-color:transparent}
.hdf-page a:focus-visible{outline:2px solid #c79732;outline-offset:4px}
.hdf-serif{font-family:${DISPLAY_FONT}}
.hdf-kicker{display:inline-flex;align-items:center;gap:12px;font-size:11px;line-height:1.5;font-weight:800;letter-spacing:.23em;text-transform:uppercase;color:#ab7c1f}
.hdf-kicker::before{content:'';height:1px;width:32px;background:linear-gradient(90deg,#e67f24,#ce9a29)}
/* Compact welcome: full width of its own account content area, not viewport. */
.hdf-hero{position:relative;isolation:isolate;display:flex;align-items:center;width:100%;min-width:0;min-height:320px;height:clamp(320px,26cqw,355px);overflow:hidden;background:linear-gradient(100deg,#fff 0%,#fdfaf3 54%,#f6edde 100%);border-bottom:1px solid rgba(145,104,27,.16)}
.hdf-hero::before{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(rgba(111,87,39,.028) 1px,transparent 1px),linear-gradient(90deg,rgba(111,87,39,.028) 1px,transparent 1px);background-size:58px 58px;mask-image:linear-gradient(90deg,transparent 35%,black 100%)}
.hdf-hero::after{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,#fff 1%,rgba(255,255,255,.96) 30%,rgba(255,255,255,.64) 45%,rgba(255,255,255,.02) 68%)}
.hdf-hero-art{position:absolute;z-index:0;right:-2%;top:50%;width:58%;height:100%;max-height:100%;object-fit:contain;object-position:center;transform:translateY(-50%);pointer-events:none;animation:hdf-art-enter 1.1s var(--ease) both}
.hdf-hero-content{position:relative;z-index:3;width:100%;min-width:0;padding:24px clamp(22px,3.2cqw,54px) 26px;pointer-events:none}
.hdf-hero-copy{width:57%;min-width:0;max-width:760px;pointer-events:auto}
.hdf-title{margin:13px 0 0;font-family:${DISPLAY_FONT};font-weight:700;font-size:clamp(63px,6.2cqw,94px);line-height:.86;letter-spacing:-.054em;color:#111}
.hdf-title>span{display:block;width:max-content;max-width:100%;padding:0 0 .12em;overflow:visible}
.hdf-title .hdf-title-name{font-weight:600;font-style:italic;line-height:1.04;letter-spacing:-.045em;padding:0 0 .20em;overflow-wrap:anywhere;background:linear-gradient(120deg,#9e6a13,#c38f24 43%,#edc857 70%,#a56d0f);background-clip:text;-webkit-background-clip:text;color:transparent}
.hdf-title.hdf-long{font-size:clamp(48px,4.7cqw,72px)}
.hdf-hero-rule{height:1px;width:102px;margin-top:-.11em;background:linear-gradient(90deg,#ed8423,#d5a12f,transparent)}
.hdf-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap;margin-top:20px}
.hdf-cta{position:relative;display:inline-flex;align-items:center;justify-content:space-between;gap:18px;min-height:45px;min-width:205px;padding:0 17px;color:#fff!important;background:#181716;font-size:12px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;overflow:hidden;transition:background .3s,transform .3s,box-shadow .3s}
.hdf-cta::after{content:'';position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.19) 48%,transparent 66%);transform:translateX(-140%);transition:transform .85s var(--ease)}
.hdf-cta:hover{background:#a97618;transform:translateY(-2px);box-shadow:0 9px 20px rgba(75,48,14,.13)}
.hdf-cta:hover::after{transform:translateX(140%)}
.hdf-secondary{display:inline-flex;align-items:center;gap:12px;min-height:43px;border-bottom:1px solid rgba(40,34,24,.19);font-size:12px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;transition:color .3s,border-color .3s}
.hdf-secondary:hover{color:#af7b16;border-color:#af7b16}
.hdf-arrow{height:17px;width:17px;flex-shrink:0;transition:transform .35s var(--ease)}
.hdf-cta:hover .hdf-arrow,.hdf-studio-button:hover .hdf-arrow,.hdf-nav-row:hover .hdf-arrow{transform:translateX(4px)}
.hdf-hero-foot{display:none}
/* A shared split band, not a stack of cards. */
.hdf-compact-grid{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);width:100%;min-width:0;align-items:stretch}
.hdf-essentials{width:100%;min-width:0;display:flex;flex-direction:column;padding:27px clamp(22px,3.1cqw,52px) 20px;background:linear-gradient(145deg,#fcfaf6,#f6f1e8);border-right:1px solid rgba(133,97,35,.17)}
.hdf-essentials-lead{min-width:0;position:relative;border-bottom:1px solid rgba(44,34,16,.13);padding-bottom:14px}
.hdf-essentials-lead h2{margin:6px 0 0;font-size:clamp(36px,3.4cqw,53px);font-weight:600;line-height:1.06;letter-spacing:-.035em;padding-bottom:.09em}
.hdf-essentials-lead h2 em{color:#af7e1f;font-weight:600}
.hdf-essentials-lead p{margin:0;color:#665d52;font-size:12.5px;line-height:1.6;max-width:450px}
.hdf-essentials-lead .hdf-member{display:none}
.hdf-nav{min-width:0;flex:1;display:flex;flex-direction:column}
.hdf-nav-row{position:relative;display:grid;grid-template-columns:21px 36px minmax(0,1fr) 33px;gap:clamp(10px,1.4cqw,18px);align-items:center;flex:1;min-height:76px;padding:5px 0;border-bottom:1px solid rgba(44,34,16,.11);transition:background .35s}
.hdf-nav-row:last-child{border-bottom:0}
.hdf-nav-row::after{position:absolute;content:'';left:0;right:100%;bottom:-1px;height:1px;background:linear-gradient(90deg,#c48b25,#f0d079);transition:right .55s var(--ease)}
.hdf-nav-row:hover{background:linear-gradient(90deg,rgba(228,180,83,.08),transparent)}
.hdf-nav-row:hover::after{right:0}
.hdf-nav-index{font:italic 500 13px Georgia,serif;color:#b58a3d}
.hdf-nav-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:50%;background:rgba(197,151,57,.08);color:#6d5632;transition:background .3s,color .3s,transform .3s}
.hdf-nav-icon svg{width:18px;height:18px}
.hdf-nav-row:hover .hdf-nav-icon{background:#e8d9b7;color:#a47218;transform:rotate(-7deg)}
.hdf-nav-label{display:block;min-width:0}
.hdf-nav-label strong{display:block;font:600 clamp(24px,2.1cqw,30px)/1.12 ${DISPLAY_FONT};letter-spacing:-.015em}
.hdf-nav-label small{display:block;margin-top:4px;color:#665e54;font-size:12px;line-height:1.5}
.hdf-nav-go{width:30px;height:30px;display:grid;place-items:center;border:1px solid rgba(183,138,46,.28);border-radius:50%;color:#a57924;transition:background .3s,color .3s}
.hdf-nav-go svg{width:15px;height:15px}
.hdf-nav-row:hover .hdf-nav-go{background:#ad8128;color:white}
/* Dark gift atelier on same line as account essentials */
.hdf-studio{position:relative;isolation:isolate;overflow:hidden;min-width:0;width:100%;display:flex;flex-direction:column;background:#11100e;color:#f9edce}
.hdf-studio::before{content:'';position:absolute;inset:0;z-index:-2;background:radial-gradient(circle at 76% 31%,rgba(192,132,36,.18),transparent 42%),linear-gradient(120deg,#16130e,#0b0908)}
.hdf-studio::after{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;background:linear-gradient(90deg,#100e0c 0%,rgba(16,14,12,.98) 26%,rgba(16,14,12,.78) 48%,rgba(16,14,12,.12) 100%)}
.hdf-studio-image{position:absolute;z-index:-1;right:0;top:0;height:100%;width:73%;object-fit:cover;object-position:right center;filter:saturate(1.04) contrast(1.02);pointer-events:none;animation:hdf-studio-enter 1.2s var(--ease) both}
.hdf-studio-main{position:relative;z-index:2;flex:1;min-height:256px;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:24px clamp(22px,3.1cqw,52px) 22px}
.hdf-studio .hdf-kicker{color:#e8c362}
.hdf-studio-main h2{max-width:500px;margin:10px 0 0;font-size:clamp(41px,4.5cqw,67px);font-weight:600;line-height:.94;letter-spacing:-.036em;padding-bottom:.08em}
.hdf-studio-main h2 em{display:block;font-weight:600;color:#ecc65c;line-height:1.06;padding-bottom:.05em}
.hdf-studio-actions{display:flex;align-items:center;flex-wrap:wrap;gap:17px;margin-top:19px}
.hdf-studio-button{display:inline-flex;align-items:center;gap:11px;min-height:43px;padding:0 15px;color:#ffe5a1!important;border:1px solid #bd8f36;background:rgba(12,10,7,.7);font:600 18px ${DISPLAY_FONT};transition:background .3s,transform .3s}
.hdf-studio-button:hover{background:rgba(176,124,32,.18);transform:translateY(-2px)}
.hdf-studio-button svg{width:17px;height:17px}
.hdf-studio-sub-link{color:#efd18b!important;border-bottom:1px solid rgba(228,187,90,.4);padding:9px 0;text-transform:uppercase;letter-spacing:.08em;font-size:11.5px;font-weight:800;transition:color .3s}
.hdf-studio-sub-link:hover{color:#fff!important}
.hdf-reveal{animation:hdf-up .7s var(--ease) both}
@keyframes hdf-up{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@keyframes hdf-art-enter{from{opacity:0;transform:translateY(-46%) scale(1.025)}to{opacity:1;transform:translateY(-50%) scale(1)}}
@keyframes hdf-studio-enter{from{opacity:0;transform:scale(1.03)}to{opacity:1;transform:scale(1)}}
/* Respond to available dashboard column width, including fixed account sidebar. */
@container hdf-dashboard (max-width:1120px){
 .hdf-title{font-size:clamp(56px,6.7cqw,80px)}
 .hdf-hero-copy{width:60%}
 .hdf-studio-image{width:78%;opacity:.85}
 .hdf-nav-label small{font-size:11.5px}
}
@container hdf-dashboard (max-width:920px){
 .hdf-hero{height:320px;min-height:0}
 .hdf-hero-art{right:-8%;width:70%;opacity:.55}
 .hdf-hero-copy{width:74%}
 .hdf-compact-grid{grid-template-columns:1fr}
 .hdf-essentials{padding:24px clamp(20px,4cqw,34px) 16px}
 .hdf-essentials-lead{padding-bottom:9px}
 .hdf-essentials-lead h2{font-size:40px}
 .hdf-nav-row{min-height:72px}
 .hdf-studio-main{min-height:255px;padding:25px 28px}
 .hdf-studio-main h2{font-size:51px}
 .hdf-studio-image{width:64%;opacity:.92}
}
@container hdf-dashboard (max-width:570px){
 .hdf-hero{height:auto;min-height:275px}
 .hdf-hero-content{padding:24px 18px 24px}
 .hdf-hero::after{background:linear-gradient(90deg,rgba(255,255,255,.97),rgba(255,255,255,.78) 59%,rgba(255,255,255,.28))}
 .hdf-hero-copy{width:100%;max-width:none}
 .hdf-hero-art{right:-21%;top:52%;width:100%;height:100%;max-height:100%;opacity:.28;object-fit:contain}
 .hdf-kicker{font-size:10.5px;gap:10px;letter-spacing:.13em}
 .hdf-kicker::before{width:24px}
 .hdf-title{font-size:clamp(54px,11.8cqw,74px);margin-top:14px}
 .hdf-title.hdf-long{font-size:clamp(40px,9.5cqw,55px)}
 .hdf-actions{gap:12px;margin-top:14px}
 .hdf-cta{min-height:44px;min-width:0;padding:0 13px;font-size:11px}
 .hdf-secondary{min-height:42px;font-size:11px}
 .hdf-essentials{padding:24px 17px 13px}
 .hdf-essentials-lead h2{font-size:36px}
 .hdf-essentials-lead p{font-size:12px}
 .hdf-nav-row{grid-template-columns:17px 32px minmax(0,1fr) 28px;min-height:69px;gap:9px}
 .hdf-nav-index{font-size:11px}
 .hdf-nav-icon{width:32px;height:32px}
 .hdf-nav-icon svg{width:16px;height:16px}
 .hdf-nav-label strong{font-size:24px}
 .hdf-nav-label small{font-size:11.5px;line-height:1.4}
 .hdf-nav-go{width:26px;height:26px}
 .hdf-studio-main{min-height:270px;padding:28px 18px 28px}
 .hdf-studio-main h2{font-size:clamp(42px,10cqw,57px)}
 .hdf-studio-image{right:-16%;width:100%;opacity:.52}
 .hdf-studio::after{background:linear-gradient(90deg,#100e0c 0%,rgba(16,14,12,.95) 41%,rgba(16,14,12,.56) 100%)}
}
@container hdf-dashboard (max-width:350px){
 .hdf-title{font-size:49px}
 .hdf-title.hdf-long{font-size:38px}
 .hdf-actions{gap:9px}
 .hdf-secondary{font-size:10px}
 .hdf-studio-actions{gap:9px}
 .hdf-studio-button{font-size:18px}
}
/* Readable by default without sacrificing the compact editorial layout. */
.hdf-cta,.hdf-secondary,.hdf-studio-sub-link{white-space:normal;line-height:1.4}
.hdf-studio-button svg{flex-shrink:0}
@container hdf-dashboard (max-width:570px){
 .hdf-studio-sub-link{font-size:11px}
}
@media(prefers-reduced-motion:reduce){.hdf-page *,.hdf-page *::before,.hdf-page *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
`;

const Glyph = ({ children, className = "" }) => <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{children}</svg>;
const Arrow = () => <Glyph className="hdf-arrow"><path d="M4 12h16m-6-6 6 6-6 6" /></Glyph>;
const Bag = () => <Glyph><path d="M5 8h14l-1 13H6L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></Glyph>;
const Card = () => <Glyph><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h5"/></Glyph>;
const Person = () => <Glyph><circle cx="12" cy="8" r="3.5"/><path d="M5 21c.4-4.5 3.1-7 7-7s6.6 2.5 7 7"/></Glyph>;
const Gift = () => <Glyph><path d="M4 10h16v11H4V10ZM2.5 7h19v4h-19V7ZM12 7v14"/><path d="M12 7H8.7a2.6 2.6 0 1 1 2.6-2.6L12 7Zm0 0h3.3a2.6 2.6 0 1 0-2.6-2.6L12 7Z"/></Glyph>;

const ACCOUNT_LINKS = [
  { to: "/account/orders", title: "My Orders", subtitle: "Track deliveries and view previous purchases", icon: Bag },
  { to: "/account/payments", title: "Payments", subtitle: "View payment records and transaction details", icon: Card },
  { to: "/account/profile", title: "My Profile", subtitle: "Manage your personal information and preferences", icon: Person },
  { to: "/custom-hamper?mode=bulk", title: "Custom Gifting", subtitle: "Explore special requests and larger gifting orders", icon: Gift },
];

const Dashboard = () => {
  const { user } = useAuth();
  const fullName = String(user?.name || "HAMPORIUM Customer").trim();
  const firstName = fullName.split(/\s+/)[0] || "Customer";
  const longName = firstName.length > 10;
  return (
    <main className="hdf-page">
      <style>{DASHBOARD_STYLES}</style>
      <section className="hdf-hero" aria-label="My HAMPORIUM welcome">
        <img src={dashboardHeroArt} className="hdf-hero-art" alt="" aria-hidden="true" decoding="async" />
        <div className="hdf-hero-content">
          <div className="hdf-hero-copy hdf-reveal">
            <div className="hdf-kicker">MY HAMPORIUM</div>
            <h1 className={`hdf-title ${longName ? "hdf-long" : ""}`}>
              <span>Welcome,</span>
              <span className="hdf-title-name">{firstName}.</span>
            </h1>
            <div className="hdf-hero-rule" aria-hidden="true" />
            <div className="hdf-actions">
              <Link className="hdf-cta" to="/gifts">Continue Shopping <Arrow /></Link>
              <Link className="hdf-secondary" to="/account/profile">View Profile <span aria-hidden="true">&#8599;</span></Link>
            </div>
          </div>
        </div>
        <div className="hdf-hero-foot"><span>Your private gifting space</span><span>The art of gifting / HAMPORIUM</span></div>
      </section>

      <div className="hdf-compact-grid">
      <section className="hdf-essentials" aria-labelledby="hdf-account-heading">
        <div className="hdf-essentials-lead">
          <div className="hdf-kicker">Your Account</div>
          <h2 className="hdf-serif" id="hdf-account-heading">Your <em>essentials.</em></h2>
          <p className="hdf-member">{fullName}</p>
        </div>
        <nav className="hdf-nav" aria-label="Account navigation">
          {ACCOUNT_LINKS.map((item, index) => {
            const ItemIcon = item.icon;
            return <Link to={item.to} className="hdf-nav-row" key={item.to}>
              <span className="hdf-nav-index">{String(index + 1).padStart(2, "0")}</span>
              <span className="hdf-nav-icon"><ItemIcon /></span>
              <span className="hdf-nav-label"><strong>{item.title}</strong><small>{item.subtitle}</small></span>
              <span className="hdf-nav-go"><Arrow /></span>
            </Link>;
          })}
        </nav>
      </section>

      <section className="hdf-studio" aria-labelledby="hdf-studio-heading">
        <img src={dashboardStudioArt} alt="" className="hdf-studio-image" aria-hidden="true" loading="lazy" decoding="async" />
        <div className="hdf-studio-main">
          <div className="hdf-kicker">The Gifting Studio</div>
          <h2 className="hdf-serif" id="hdf-studio-heading">Custom &amp; Bulk <em>gifting.</em></h2>
          <div className="hdf-studio-actions">
            <Link to="/custom-hamper" className="hdf-studio-button"><Gift /> Build Your Hamper <Arrow /></Link>
            <Link to="/custom-hamper?mode=bulk" className="hdf-studio-sub-link">Start Bulk Order &#8599;</Link>
          </div>
        </div>
      </section>
      </div>
    </main>
  );
};

export default Dashboard;
